_APPLY_HREF_SETTLE_LIMIT = 2
_ACTIVATION_PASS_LIMIT = 3
_APPLY_SELECTOR_RENDER_WAIT_MS = 5 * 10**3
_MIN_APPLICATION_FORM_CONTROLS = 2

async def activate_apply_flow_if_needed(
    page: Page,
    target_url: str,
    timeout_ms: int,
) -> None:
    for _pass_index in range(_ACTIVATION_PASS_LIMIT):
        if await page_has_application_form(page):
            return

        if await _try_navigate_external_apply_href(page, target_url):
            if (
                await page_has_application_form(page)
                or await page.locator(
                    "input:not([type='hidden']):visible, textarea:visible, select:visible"
                ).count()
                > 0
            ):
                return
            continue

        host = urlparse(page.url).netloc.lower() or urlparse(target_url).netloc.lower()
        if await _navigate_workday_manual_apply(page, before_url=page.url):
            return
        selectors = _platform_apply_selectors(host)
        if selectors and _pass_index == 0:
            await _wait_for_apply_selector_render(page, selectors)
        advanced = False
        for selector in selectors:
            before_url = page.url
            if await _try_click_apply_selector(page, selector, timeout_ms):
                return
            if page.url != before_url:
                advanced = True
                break
        if not advanced:
            await _wait_for_application_form(page)
            return


async def _wait_for_apply_selector_render(
    page: Page,
    selectors: list[str],
) -> None:
    """Wait a bounded window for one platform apply selector to render."""
    try:
        await page.wait_for_selector(
            ", ".join(selectors),
            state="visible",
            timeout=_APPLY_SELECTOR_RENDER_WAIT_MS,
        )
    except (RuntimeError, Error, ValueError):
        return
